) as payload (
  book_id integer,
  segment_key text,
  source_key text,
  segment_order integer,
  segment_index integer,
  segment_count integer,
  boundary_version integer,
  start_locator jsonb,
  end_locator jsonb,
  display_title text,
  approval_status text
)
order by
  payload.book_id,
  payload.segment_order;

do $vereda_postconditions$
declare
  v_segment_count bigint;
begin
  select count(*)
  into v_segment_count
  from content_staging.reading_segments
  where run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid;

  if v_segment_count <> 812 then
    raise exception
      'Expected 812 segment proposals, inserted %',
      v_segment_count;
  end if;

  if exists (
    select 1
    from content_staging.reading_segments
    where run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
      and (
        approval_status <> 'boundary-review'
        or content is not null
        or word_count is not null
        or normalized_content_sha256 is not null
      )
  ) then
    raise exception
      'PR-0018 design rows must remain content-free and unapproved';
  end if;

  if exists (
    select 1
    from content_staging.current_successor_mappings
  ) or exists (
    select 1
    from content_staging.dependency_snapshots
  ) or exists (
    select 1
    from content_staging.dry_run_results
  ) then
    raise exception
      'PR-0018 cannot populate downstream migration entities';
  end if;
end;
$vereda_postconditions$;

insert into content_staging.migration_audit_events (
  run_id,
  event_type,
  details
)
values (
  'adcff561-8f92-545c-a219-615818a454f4'::uuid,
  'reading-segment-design-loaded',
  jsonb_build_object(
    'segment_proposal_count',
    812,
    'boundary_version',
    1,
    'approval_status',
    'boundary-review',
    'contains_full_text',
    false,
    'successor_mapping_count',
    0,
    'dependency_snapshot_count',
    0,
    'cutover_enabled',
    false
  )
);

update content_staging.migration_runs
set
  status = 'reviewing',
  updated_at = now()
where id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid;

commit;
